import {runBrowserOperation} from './nstack-browser';
import QRCode from 'qrcode';
import {INVITE_KEY,inviteCode,inviteUrl} from './invite';
import {imageComposer,imageReferences,mountInterviewImages,draftImages,clearDraftImages,imageUploadBusy} from './interview-images';
import {renderMarkdown} from './markdown';
import {nstackSettings,nstackPermissions,attachNStackBridge,openNStackApp} from './nstack';
import {generateSecretKey,finalizeEvent,nip19,nip44,getPublicKey} from 'nostr-tools';
import {readNostrProfile,verifiedProfile,isChatSubmitKey} from './identity';

type RecordData = Record<string, any>;
declare global {interface Window {nostr?: {getPublicKey():Promise<string>;signEvent(event:RecordData):Promise<any>;nip44?:{decrypt(pubkey:string,ciphertext:string):Promise<string>}}}}
const app=document.querySelector<HTMLDivElement>('#app')!;
const KEY='byo-freedom.identity.v1', MODE='byo-freedom.signer.v1';
const incomingInvite=inviteCode(new URL(location.href));
if(incomingInvite){sessionStorage.setItem(INVITE_KEY,incomingInvite);history.replaceState(null,'','/'+location.hash);}
let inviteAttempt:Promise<string>|null=null;
async function joinPendingInvite(){const code=sessionStorage.getItem(INVITE_KEY);if(!code)return null;if(!inviteAttempt)inviteAttempt=api('/api/join','POST',{code}).then(result=>{sessionStorage.removeItem(INVITE_KEY);sessionStorage.removeItem('byo-freedom.return-app');return '#/projects/'+result.id;}).finally(()=>{inviteAttempt=null});return inviteAttempt;}

let me:RecordData|null=null, projects:RecordData[]=[], current:RecordData|null=null;
let tab=localStorage.getItem('byo-freedom.tab')||'chat', selectedSnapshot:string|null=null, selectedVersion:string|null=null, editing=false, generation=0, pollTimer:ReturnType<typeof setTimeout>|undefined;
let activeRoute='', lastRenderKey='', busy=false,chatComposing=false,lastChatCompositionEnd=0;
const e=(s:any)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const safeUrl=(s:any)=>{if(!s||!String(s).trim())return '';try{const u=new URL(String(s),location.origin);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const date=(s:any)=>{const d=new Date(s);return Number.isNaN(d.valueOf())?'':d.toLocaleDateString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})};
const bytesHex=(b:Uint8Array)=>Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');
const hexBytes=(h:string)=>new Uint8Array(h.match(/.{2}/g)!.map(s=>parseInt(s,16)));
const sha=async(data:BufferSource)=>bytesHex(new Uint8Array(await crypto.subtle.digest('SHA-256',data)));
const storageGet=(k:string)=>{try{return localStorage.getItem(k)}catch{return null}};
function toast(message:string){const t=document.querySelector<HTMLDivElement>('#toast')!;t.textContent=message;t.style.display='block';setTimeout(()=>t.style.display='none',4500)}
function fail(error:any){toast(error instanceof Error?error.message:String(error))}
async function sign(event:RecordData){if(event.kind===0)throw new Error('BYO Freedom never publishes Nostr profiles.');if(storageGet(MODE)==='extension'){if(!window.nostr)throw new Error('Your Nostr signer is unavailable. Open this page in your signer’s browser or reconnect it.');return window.nostr.signEvent(event)}const key=storageGet(KEY);if(!key)throw new Error('Please sign in again.');return finalizeEvent(event as any,hexBytes(key))}
function nstackSigner(){
 if(storageGet(MODE)==='extension'){
  if(!window.nostr)throw new Error('Your Nostr signer is unavailable. Reconnect it and retry.');
  return window.nostr;
 }
 const key=storageGet(KEY);if(!key)throw new Error('Please sign in again.');
 return {getPublicKey:async()=>getPublicKey(hexBytes(key)),signEvent:sign,nip44:{decrypt:async(pubkey:string,ciphertext:string)=>nip44.v2.decrypt(ciphertext,nip44.v2.utils.getConversationKey(hexBytes(key),pubkey))}};
}
async function api(path:string,method='GET',data?:RecordData,options?:{signal?:AbortSignal}){options?.signal?.throwIfAborted();const url=new URL(path,location.origin).href;const body=data===undefined?undefined:JSON.stringify(data);const tags=[['u',url],['method',method],['nonce',crypto.randomUUID()]];if(body!==undefined)tags.push(['payload',await sha(new TextEncoder().encode(body))]);options?.signal?.throwIfAborted();const event=await sign({kind:27235,created_at:Math.floor(Date.now()/1000),tags,content:''});options?.signal?.throwIfAborted();const auth=btoa(JSON.stringify(event));const res=await fetch(url,{method,body,signal:options?.signal,headers:{Authorization:`Nostr ${auth}`,...(body!==undefined?{'Content-Type':'application/json'}:{})},credentials:'omit'});const result=await res.json().catch(()=>({error:`Request failed (${res.status})`}));if(!res.ok){const err=new Error(result.error||`Request failed (${res.status})`);Object.assign(err,{status:res.status});throw err}return result}
function avatar(profile:RecordData={},large=false){const url=safeUrl(profile.avatar);return url?`<img class="avatar ${large?'profile-avatar':''}" src="${e(url)}" alt="${e(profile.name||'Your avatar')}" referrerpolicy="no-referrer">`:`<span class="avatar ${large?'profile-avatar':''}" aria-hidden="true">${e((profile.name||'You').slice(0,1).toUpperCase())}</span>`}
function header(){return `<header class="topbar"><a class="brand" href="#/projects"><span class="mark" aria-hidden="true"></span>BYO Freedom</a><div class="top-actions">${me?`${me.admin?'<span class="admin-badge">Admin workshop</span>':''}<button class="account" data-action="profile" aria-label="Open your profile">${avatar(me.profile)}<span class="account-name">${e(me.profile?.name||'Your profile')}</span></button>`:'<span class="eyebrow" style="margin:0">Ideas into independence</span>'}</div></header>`}
function breadcrumb(items:Array<[string,string?]>){return `<nav class="crumb" aria-label="Breadcrumb">${items.map(([label,route],i)=>`${i?'<span aria-hidden="true">/</span>':''}${route?`<a href="#${e(route)}">${e(label)}</a>`:`<span>${e(label)}</span>`}`).join('')}</nav>`}
function renderEntry(){app.innerHTML=header()+`<main class="entry"><section><div class="eyebrow">Bring your own freedom</div><h1>A little idea.<br>A little <em>more free.</em></h1><p class="entry-copy">What would give you more freedom? Explore it with an agent, shape a design, and help bring something useful into the world.</p><div class="entry-meta"><span>Freedom & Bitcoin</span><span>Your words. Your ideas.</span></div></section><section class="entry-card"><div class="eyebrow">Your workshop starts here</div><h2>${sessionStorage.getItem(INVITE_KEY)?'Join your project.':'Make room for your ideas.'}</h2>${sessionStorage.getItem(INVITE_KEY)?'<p class="help">Your project invitation is saved. Sign in or create an account to join and open it automatically.</p>':''}<p class="muted">No account forms. Start with a private browser identity, or use your Nostr signer.</p><button class="primary" data-action="anon">Create anonymous account <span aria-hidden="true">↗</span></button><button data-action="extension">Log in with Nostr extension</button><p class="help">Your anonymous key stays in this browser. Clearing its storage or changing devices loses access unless you export your recovery key.</p><div class="divider"></div><button class="text-button small" data-action="import">Restore a recovery key</button><p class="help">On a phone, use a NIP-07 compatible signer browser to sign in with an existing Nostr identity.</p></section></main>`}
async function loadMe(){const account=await api('/api/me');account.appProfile={...account.profile};if(storageGet(MODE)==='extension'){let profile=null;try{const lookup=await api('/api/profile/nostr');profile=verifiedProfile(lookup.profile?.event,account.pubkey);}catch{}if(!profile)profile=await readNostrProfile(account.pubkey);if(profile){account.profile={name:profile.name||account.profile?.name||'Nostr identity',avatar:profile.avatar};account.nostrProfile={eventId:profile.event.id,createdAt:profile.event.created_at};}}me=account;return me}
function loginDestination(){const path=sessionStorage.getItem('byo-freedom.return-app');sessionStorage.removeItem('byo-freedom.return-app');return path&&/^\/apps\/[^/?#]+$/.test(path)?'#'+path:null;}
async function login(mode:string){if(mode==='anon'){let key=storageGet(KEY);if(!key){key=bytesHex(generateSecretKey());localStorage.setItem(KEY,key)}localStorage.setItem(MODE,'anonymous')}else{if(!window.nostr)throw new Error('No NIP-07 signer found. Use a compatible Nostr extension or signer browser, or create an anonymous account.');await window.nostr.getPublicKey();localStorage.setItem(MODE,'extension')}await loadMe();location.hash=loginDestination()||(mode!=='anon'||me!.profile?.name?'#/projects':'#/profile');await route()}
function modal(title:string,html:string,onSubmit?:(form:HTMLFormElement)=>Promise<void>){document.querySelector('.modal-backdrop')?.remove();const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${e(title)}</h2><button type="button" class="small ghost" data-close aria-label="Close dialog">✕</button></div><form>${html}</form></section>`;document.body.append(backdrop);const close=()=>backdrop.remove();backdrop.querySelector('[data-close]')!.addEventListener('click',close);backdrop.addEventListener('click',ev=>{if(ev.target===backdrop)close()});backdrop.addEventListener('keydown',ev=>{if(ev.key==='Escape')close()});const form=backdrop.querySelector('form')!;form.addEventListener('submit',async ev=>{ev.preventDefault();const submit=form.querySelector<HTMLButtonElement>('[type=submit]');if(submit)submit.disabled=true;try{await onSubmit?.(form);close()}catch(err){let box=form.querySelector('.error-box');if(!box){box=document.createElement('div');box.className='error-box';box.setAttribute('role','alert');form.prepend(box)}box.textContent=(err as Error).message}finally{if(submit)submit.disabled=false}});backdrop.querySelector<HTMLElement>('input,textarea,select,button')?.focus();return backdrop}
function restore(){modal('Restore your browser identity',`<p class="muted">Enter the recovery key you exported from BYO Freedom. It is stored only in this browser and is never sent to the server.</p><label>Recovery key<input name="key" type="password" autocomplete="off" spellcheck="false" required placeholder="nsec1…"></label><div class="modal-actions"><button class="primary" type="submit">Restore account</button></div>`,async form=>{const value=String(new FormData(form).get('key')).trim();const decoded=nip19.decode(value);if(decoded.type!=='nsec')throw new Error('Please enter an nsec recovery key.');localStorage.setItem(KEY,bytesHex(decoded.data));localStorage.setItem(MODE,'anonymous');await loadMe();location.hash=loginDestination()||'#/projects';await route()})}
function exportKey(){const key=storageGet(KEY);if(storageGet(MODE)==='extension'||!key){toast('Your Nostr signer manages this account’s recovery key.');return}const nsec=nip19.nsecEncode(hexBytes(key));modal('Save your recovery key',`<p>Anyone with this key can act as you. Keep it somewhere private so you can recover your designs on another device.</p><label>Private recovery key<textarea readonly rows="3" autocomplete="off" spellcheck="false">${e(nsec)}</textarea></label><div class="modal-actions"><button type="button" data-download>Download recovery file</button><button type="submit" class="primary">I have saved it</button></div>`).querySelector('[data-download]')!.addEventListener('click',()=>{const blob=new Blob([`BYO Freedom private recovery key\n\n${nsec}\n\nKeep this private. Anyone with this key can access your account.\n`],{type:'text/plain'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='byo-freedom-recovery.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function profile(){if(!me)await loadMe();if(storageGet(MODE)==='extension'){renderNostrIdentity();return;}app.innerHTML=header()+`<main class="shell">${breadcrumb([['My Projects','/projects'],['Your profile']])}<div class="eyebrow">A name to your ideas</div><h1>Your corner of the workshop.</h1><p class="intro">Choose what people call you. A first name or a nickname is plenty.</p><form id="profile-form" class="form-grid"><div class="profile-upload">${avatar(me!.profile,true)}<div><label>Upload an avatar<input type="file" id="avatar-file" accept="image/jpeg,image/png,image/webp,image/gif"></label><p class="help">Uploaded directly to blossom.primal.net with your Nostr signature. Your picture will be public.</p><p class="help" id="upload-status" role="status"></p></div></div><label>Name<input name="name" value="${e(me!.profile?.name)}" maxlength="100" required autocomplete="nickname"></label><label>Avatar URL<input name="avatar" type="url" value="${e(me!.profile?.avatar)}" placeholder="https://…"></label><div class="row"><button class="primary" type="submit">Save profile</button><button type="button" data-action="projects">Back to projects</button></div></form><div class="divider"></div><div class="form-grid"><h2>Your identity</h2><p class="code muted">${e(me!.pubkey?nip19.npubEncode(me!.pubkey):'')}</p><p class="help">${storageGet(MODE)==='extension'?'You are signing with your Nostr extension. Your signer keeps your private key.':'Your anonymous identity is stored in this browser. Browser storage is not a backup. Save your recovery key before clearing storage or switching devices.'}</p><div class="row"><button data-action="export">Export recovery key</button><button class="ghost" data-action="logout">Sign out</button></div></div></main>`;document.querySelector('#profile-form')!.addEventListener('submit',async ev=>{ev.preventDefault();await act(async()=>{const f=new FormData(ev.target as HTMLFormElement);await api('/api/profile','PATCH',{name:f.get('name'),avatar:f.get('avatar')});await loadMe();toast('Profile saved');location.hash='#/projects'})});document.querySelector('#avatar-file')!.addEventListener('change',uploadAvatar)}
function renderNostrIdentity(){app.innerHTML=header()+`<main class="shell">${breadcrumb([['My Projects','/projects'],['Your Nostr identity']])}<div class="eyebrow">Your existing identity</div><h1>Your Nostr profile.</h1><div class="card form-grid"><div class="profile-upload">${avatar(me!.profile,true)}<div><h2>${e(me!.profile?.name||'Nostr identity')}</h2><p class="help">${me!.nostrProfile?'Read from your verified, signed Nostr profile.':'Showing your existing app profile. A verified Nostr profile is not available right now.'}</p></div></div><p class="code muted">${e(nip19.npubEncode(me!.pubkey))}</p><p class="muted">Your Nostr signer manages this identity. BYO Freedom reads your profile and never publishes or changes it.</p><div class="row"><button class="primary" data-action="projects">Back to projects</button><button class="ghost" data-action="logout">Sign out</button></div></div></main>`;}
async function uploadAvatar(ev:Event){const file=(ev.target as HTMLInputElement).files?.[0];if(!file)return;const status=document.querySelector('#upload-status')!;try{if(file.size>5*1024*1024)throw new Error('Choose a picture smaller than 5 MB.');if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw new Error('Choose a JPG, PNG, WebP or GIF picture.');status.textContent='Signing and uploading your picture…';const hash=await sha(await file.arrayBuffer());const now=Math.floor(Date.now()/1000);const event=await sign({kind:24242,created_at:now,content:'Upload BYO Freedom profile picture',tags:[['t','upload'],['x',hash],['expiration',String(now+300)]]});const res=await fetch('https://blossom.primal.net/upload',{method:'PUT',body:file,headers:{Authorization:`Nostr ${btoa(JSON.stringify(event))}`,'Content-Type':file.type},credentials:'omit'});if(!res.ok)throw new Error(`Blossom rejected the upload (${res.status}).`);const info=await res.json();const url=safeUrl(info.url);if(!url||new URL(url).protocol!=='https:')throw new Error('Blossom did not return a valid HTTPS image URL.');(document.querySelector('[name=avatar]') as HTMLInputElement).value=url;status.textContent='Uploaded. Save your profile to use this picture.'}catch(err){status.textContent=`Upload unavailable: ${(err as Error).message} Your browser or the Blossom server may restrict this request. You can enter an existing public image URL instead.`}}
async function renderProjects(){const data=await api('/api/projects');projects=data.projects||[];app.innerHTML=header()+`<main class="shell"><div class="heading-row"><div><div class="eyebrow">A place to make things happen</div><h1>My Projects</h1><p class="intro">Find your people. Bring an idea. See where it goes.</p></div>${me!.admin?'<button class="primary" data-action="new-project">+ Create project</button>':''}</div><form class="join-row" id="join-form"><label>Have a project code?<input name="code" placeholder="Enter your join code" required autocapitalize="characters" autocomplete="off"></label><button type="submit">Join project <span aria-hidden="true">↗</span></button></form>${projects.length?`<div class="section-row"><h2>Your workshops <span class="muted">(${projects.length})</span></h2></div><div class="cards">${projects.map(p=>`<button class="card project-card" data-project="${e(p.id)}"><div><div class="eyebrow">Project workshop</div><h3>${e(p.title)}</h3><p class="muted" style="font-size:.85rem">${e(p.description||'A shared space for independent ideas.')}</p></div><div class="card-footer"><span>Open project</span><span class="arrow" aria-hidden="true">↗</span></div></button>`).join('')}</div>`:`<div class="empty" style="margin-top:35px"><h3>Your next idea needs a home.</h3><p>Join a project with a code from your event organiser. Featured events appear here automatically while admission is open.</p></div>`}${me!.admin?`<section class="project-admin"><div class="section-row"><h2>Featured event</h2><button data-action="nstack-settings" class="small">NStack data connection</button><button class="small" data-action="featured">Manage auto admission</button></div><p class="help">A featured event automatically admits new visitors until the time you choose. ${data.settings?.featuredProjectId?`Current event: ${e(projects.find(p=>p.id===data.settings.featuredProjectId)?.title||data.settings.featuredProjectId)}. Until ${e(date(data.settings.featuredUntil))}.`:'No featured event is selected.'}</p></section>`:''}<p class="footer-note">Built around your ideas, with freedom and Bitcoin at the heart of the conversation.</p></main>`;document.querySelector('#join-form')!.addEventListener('submit',ev=>{ev.preventDefault();act(async()=>{const r=await api('/api/join','POST',{code:new FormData(ev.target as HTMLFormElement).get('code')});toast('You joined the project');location.hash=`#/projects/${r.project?.id||r.projectId||r.id}`})});document.querySelectorAll('[data-project]').forEach(el=>el.addEventListener('click',()=>location.hash=`#/projects/${el.getAttribute('data-project')}`))}
function createProject(){modal('Create a project',`<div class="form-grid"><label>Project name<input name="title" required maxlength="160" placeholder="Parkes Bush Bash 2026"></label><label>A little about it<textarea name="description" rows="3" maxlength="3000" placeholder="What brings this group together?"></textarea></label></div><div class="modal-actions"><button class="primary" type="submit">Create project</button></div>`,async form=>{const f=new FormData(form);const r=await api('/api/projects','POST',{title:f.get('title'),description:f.get('description')});location.hash=`#/projects/${r.project?.id||r.id}`})}
function featured(){modal('Feature an event',`<p class="muted">Visitors automatically join this project while its admission window is open.</p><div class="form-grid"><label>Project<select name="project"><option value="">No featured event</option>${projects.map(p=>`<option value="${e(p.id)}" ${p.id===me!.settings?.featuredProjectId?'selected':''}>${e(p.title)}</option>`).join('')}</select></label><label>Admission closes (your local time)<input name="until" type="datetime-local" value="${new Date(Date.now()+3*86400000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></label></div><div class="modal-actions"><button class="primary" type="submit">Save admission window</button></div>`,async form=>{const f=new FormData(form);const id=f.get('project');const until=String(f.get('until'));if(id&&!until)throw new Error('Choose when automatic admission closes.');await api('/api/settings','PATCH',{featuredProjectId:id||null,featuredUntil:id?new Date(until).toISOString():null});await loadMe();await renderProjects();toast('Featured event updated')})}
async function renderProject(id:string){const data=await api(`/api/projects/${encodeURIComponent(id)}`);current=data;const p=data.project;app.innerHTML=header()+`<main class="shell">${breadcrumb([['My Projects','/projects'],[p.title]])}<div class="project-heading"><div class="project-title-row"><h1>${e(p.title)}</h1><a class="primary site-link" href="/sites/${encodeURIComponent(p.id)}" target="_blank" rel="noopener">View project site <span aria-hidden="true">↗</span></a></div><p class="intro">${e(p.description||'Bring a question, a tool you wish existed, or a trick worth sharing.')}</p></div>${data.apps?.length?`<section aria-label="Project apps"><div class="section-row"><h2>Project apps</h2></div><p class="help">Use installed apps with saved data. Designs and interviews remain private.</p><div class="design-list">${data.apps.map((a:RecordData)=>`<a class="card design-row" href="#/apps/${e(a.versionId)}" data-project-app="${e(a.versionId)}"><div><h3>${e(a.title)}</h3><p>Version ${e(a.number)} · Saved app data</p></div><span class="arrow">↗</span></a>`).join('')}</div></section>`:''}<div class="section-row"><h2>My Designs</h2><button class="primary" data-action="new-design">+ New design</button></div>${data.designs?.length?`<div class="design-list">${data.designs.map((d:RecordData)=>designCard(d,false)).join('')}</div>`:`<div class="empty"><h3>The first step is to express what you want.</h3><p>Click <strong>+ New design</strong>. An agent will guide you through an unstructured interview to build out a design for something you can add to the site. Think about what you want, how it works, and ask questions if you’re unsure. You’ll see the design built alongside the chat.</p><button data-action="new-design">Start your first interview <span aria-hidden="true">↗</span></button></div>`}${me!.admin?`<section class="project-admin"><div class="section-row"><h2>Create Artefacts</h2><div class="row"><a class="small" href="#/projects/${e(p.id)}/site">Site Builder ↗</a><span class="badge">Admin only</span></div></div><p class="muted" style="font-size:.88rem">Choose one of your designs, or someone else’s, then select the exact revision of a visible design to implement.</p><div class="design-list">${data.availableDesigns?.length?data.availableDesigns.map((d:RecordData)=>designCard(d,true)).join(''):'<p class="help">Designs will appear here as people begin their interviews.</p>'}</div>${data.implementations?.length?`<div class="section-row"><h3>Implementation conversations</h3></div><div class="design-list">${data.implementations.map((i:RecordData)=>`<button class="card design-row" data-implementation="${e(i.id)}"><div><h3>${e(i.title||data.availableDesigns?.find((d:RecordData)=>d.id===i.designId)?.title||'Implementation conversation')}</h3><p>Separate admin chat · ${e(date(i.createdAt))}</p></div><span class="arrow">↗</span></button>`).join('')}</div>`:''}<div class="section-row"><h3>Project settings</h3><div class="row"><button class="small" data-action="share-project">Share project · QR code</button><button class="small" data-action="project-settings">Edit project & join code</button></div></div><p class="help">Join code: <strong class="code">${e(p.joinCode||'Not available')}</strong></p></section>`:''}</main>`;document.querySelectorAll('[data-design]').forEach(el=>el.addEventListener('click',()=>location.hash=`#/designs/${el.getAttribute('data-design')}`));document.querySelectorAll('[data-build]').forEach(el=>el.addEventListener('click',()=>act(()=>selectImplementation(el.getAttribute('data-build')!))));document.querySelectorAll('[data-implementation]').forEach(el=>el.addEventListener('click',()=>location.hash=`#/implementations/${el.getAttribute('data-implementation')}`))}
function designCard(d:RecordData,build:boolean){return `<button class="card design-row" ${build?`data-build="${e(d.id)}"`:`data-design="${e(d.id)}"`}><div><h3>${e(d.title||'New design')}</h3><p>${build?'Select a design to implement':'Continue your interview'}${d.updatedAt?' · '+e(date(d.updatedAt)):''}</p></div><span class="arrow" aria-hidden="true">${build?'+':'↗'}</span></button>`}
async function newDesign(){const p=current!.project;const r=await api(`/api/projects/${encodeURIComponent(p.id)}/designs`,'POST',{});location.hash=`#/designs/${r.design?.id||r.id}`}
async function shareProject(){const p=current!.project;if(!me?.admin||!p.joinCode)throw Error('Project sharing is available to admins.');const url=inviteUrl(location.origin,p.joinCode);const box=modal('Share '+p.title,`<p>Share this link or QR code. After signing in or creating an account, visitors join this project and open it automatically.</p><p class="help">Anyone with this code can join as a participant. Change the join code in Project settings to stop future joins with this link.</p><label>Project invitation URL<input id="invite-url" readonly value="${e(url)}"></label><div class="modal-actions"><button type="button" id="invite-copy">Copy full URL</button></div><canvas id="invite-qr" role="img" aria-label="Project invitation QR code" style="display:block;max-width:100%;height:auto;margin:16px auto"></canvas><p class="help" id="invite-copy-status" role="status"></p>`);const input=box.querySelector<HTMLInputElement>('#invite-url')!;box.querySelector('#invite-copy')!.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url);box.querySelector('#invite-copy-status')!.textContent='Invitation URL copied';}catch{input.focus();input.select();box.querySelector('#invite-copy-status')!.textContent='Select and copy the invitation URL above.';}});await QRCode.toCanvas(box.querySelector<HTMLCanvasElement>('#invite-qr')!,url,{width:320,margin:4,errorCorrectionLevel:'M'});}
function projectSettings(){const p=current!.project;modal('Project settings',`<div class="form-grid"><label>Project name<input name="title" required maxlength="160" value="${e(p.title)}"></label><label>Description<textarea name="description" rows="3">${e(p.description)}</textarea></label><label>Join code<input name="joinCode" required value="${e(p.joinCode)}" autocomplete="off"></label></div><div class="modal-actions"><button type="button" class="danger" data-action="delete-project">Delete project</button><button class="primary" type="submit">Save changes</button></div>`,async form=>{await api(`/api/projects/${p.id}`,'PATCH',{title:new FormData(form).get('title'),description:new FormData(form).get('description'),joinCode:new FormData(form).get('joinCode')});await renderProject(p.id);toast('Project settings saved')})}
function deleteProject(){const p=current!.project;modal('Delete project',`<p>Delete <strong>${e(p.title)}</strong> and remove its entire public site, including all published contributions? Members will lose access to its interviews and apps. This is a project deletion, not a single design removal.</p><p class="help">Records and version history are retained privately for operator recovery. This cannot be undone here.</p><label>Type the project name to confirm<input name="confirmTitle" required autocomplete="off" aria-label="Project name to confirm deletion"></label><div class="modal-actions"><button type="button" data-action="project-settings">Cancel</button><button type="submit" class="danger">Delete project and site</button></div>`,async form=>{await api(`/api/projects/${p.id}`,'DELETE',{confirmTitle:new FormData(form).get('confirmTitle')});location.hash='#/projects';toast('Project and public site removed')})}
async function selectImplementation(designId:string){const data=await api(`/api/designs/${designId}/snapshots`);const snaps=(data.milestones||[]).map((m:RecordData)=>({...m,id:m.snapshotId}));const versions=allVersions(data);if(!snaps.length)throw new Error('This design needs a saved snapshot before it can be implemented.');modal('Create an artefact',`<p class="muted">Start a separate admin conversation for <strong>${e(data.design.title)}</strong>. The selected snapshot stays pinned throughout the build.</p><div class="form-grid"><label>Design milestone<select name="snapshotId">${[...snaps].reverse().map((s:RecordData,i:number)=>`<option value="${e(s.id)}">Design ${e(s.number)} · ${e(s.title||'Design')} · ${s.state==='built'?'built, exact revision':'draft, latest revision'}${i===0?' · latest':''}</option>`).join('')}</select></label><label>Starting artefact version<select name="startingVersionId"><option value="">Start a new artefact</option>${versions.map(v=>`<option value="${e(v.id)}">${e(v.artifactTitle)} · Version ${e(v.number)}</option>`).join('')}</select></label></div><div class="modal-actions"><button class="primary" type="submit">Open implementation chat</button></div>`,async form=>{const f=new FormData(form);const r=await api(`/api/designs/${designId}/implementations`,'POST',{snapshotId:f.get('snapshotId'),startingVersionId:f.get('startingVersionId')||null});location.hash=`#/implementations/${r.implementation?.id||r.id}`})}
function allVersions(data:RecordData):RecordData[]{return (data.artifacts||[]).flatMap((a:RecordData)=>(a.versions||[]).map((v:RecordData)=>({...v,artifactId:a.id,artifactTitle:a.title}))).sort((a:RecordData,b:RecordData)=>new Date(a.createdAt||0).valueOf()-new Date(b.createdAt||0).valueOf())}
const draftKey=(kind:string,id:string)=>`byo-freedom.draft.${kind}.${id}`;
function saveWorkspaceState(){const composer=document.querySelector<HTMLTextAreaElement>('#message-input');if(composer&&current){localStorage.setItem(draftKey(current.implementation?'implementation':'design',current.implementation?.id||current.design.id),composer.value)}const edit=document.querySelector<HTMLTextAreaElement>('#document-editor');if(edit&&current)sessionStorage.setItem(`byo-freedom.edit.${current.design.id}`,edit.value)}
async function workspace(kind:string,id:string,refresh=false){const token=generation;const data=await api(`/api/${kind==='design'?'designs':'implementations'}/${encodeURIComponent(id)}`);if(token!==generation)return;const routeKey=`${kind}/${id}`;const versions=allVersions(data);const snaps=data.snapshots||(data.snapshot?[data.snapshot]:[]);const job=(data.jobs||[]).filter((j:RecordData)=>!['complete','completed','succeeded','failed','error','cancelled','conflict','superseded'].includes(j.status)).at(-1);const failed=(data.jobs||[]).filter((j:RecordData)=>['failed','error','interrupted','conflict'].includes(j.status)).at(-1);const renderKey=JSON.stringify({data,selectedSnapshot,selectedVersion,editing},(key,value)=>key==='previewUrl'?undefined:value);if(refresh&&(editing||chatComposing||imageUploadBusy(id)||lastRenderKey===renderKey)){schedulePoll(kind,id,!!job);return}saveWorkspaceState();const messagesEl=document.querySelector('.messages');const previousScroll=messagesEl?.scrollTop||0;const atBottom=!messagesEl||messagesEl.scrollHeight-messagesEl.clientHeight-previousScroll<70;const editor=document.querySelector<HTMLTextAreaElement>('#document-editor');const editorScroll=editor?.scrollTop||0;const wasFocused=(document.activeElement as HTMLElement)?.id;const selection=wasFocused==='message-input'?(document.activeElement as HTMLTextAreaElement).selectionStart:null;current=data;activeRoute=routeKey;lastRenderKey=renderKey;const design=data.design;const impl=data.implementation;const latest=snaps.find((s:RecordData)=>s.id===design.currentSnapshotId)||snaps.at(-1);const snap=snaps.find((s:RecordData)=>s.id===selectedSnapshot)||latest;const version=versions.find(v=>v.id===selectedVersion);const content=version?`<iframe sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer" title="${e(version.artifactTitle)} — version ${e(version.number)}" src="${e(version.previewUrl||`/preview/${version.id}/index.html`)}"></iframe>`:editing?`<textarea id="document-editor" class="document-editor" aria-label="Design document" spellcheck="true">${e(sessionStorage.getItem(`byo-freedom.edit.${design.id}`)??snap?.document??'')}</textarea>`:snap?`<article class="document markdown-content">${renderMarkdown(snap.document||'')}</article>`:`<div class="empty"><h3>Your design grows with the conversation.</h3><p>Tell the agent what you have in mind. Each reply saves an immutable revision. A new visible design begins after a successful artefact build.</p></div>`;
app.innerHTML=header()+`<main class="workspace-shell">${breadcrumb([['My Projects','/projects'],['Project',`/projects/${design.projectId}`],[kind==='design'?'Your design':'Implementation']])}<div class="workspace-heading"><div><h1>${kind==='design'?`<button class="title-edit" data-action="rename" title="Edit design title">${e(design.title||'New design')} <span class="muted" style="font-size:.75rem">✎</span></button>`:e(design.title)}</h1><p class="muted">${kind==='design'?'A conversation to develop your idea':'Admin implementation conversation'}</p></div><div class="row">${me!.admin?'<button class="small" data-action="design-brand">Brand exceptions</button>':''}${kind==='design'&&me!.admin?'<button class="small" data-action="implement-current">Create artefact</button>':''}<a class="small" href="/sites/${e(design.projectId)}" target="_blank" rel="noopener">Project site ↗</a></div></div>${impl?`<div class="implementation-banner"><strong>Pinned design:</strong> Design ${e(data.designPin?.designNumber||1)} · ${e(data.snapshot?.title||'Selected revision')} · ${e(date(data.snapshot?.createdAt))}${impl.startingVersionId?` · Starting version: ${e(impl.startingVersionId.slice(0,8))}`:''}. Interview changes create new snapshots and do not change this build.</div>`:''}<div class="mobile-tabs" role="tablist" aria-label="Workspace view"><button role="tab" aria-selected="${tab==='chat'}" class="${tab==='chat'?'active':''}" data-tab="chat">Chat</button><button role="tab" aria-selected="${tab==='preview'}" class="${tab==='preview'?'active':''}" data-tab="preview">Preview</button></div><div class="workspace" data-tab="${e(tab)}"><section class="panel chat-panel" aria-label="${impl?'Implementation conversation':'Design interview'}"><div class="panel-head"><span class="panel-label"><span class="dot ${impl?'orange':''}"></span>${impl?'Implementation chat':'Your interview'}</span><span class="muted" style="font-size:.71rem">${impl?'Admin only':'Private conversation'}</span></div><div class="messages" aria-live="polite">${(data.messages||[]).length?data.messages.map((m:RecordData)=>`<div class="message ${m.role==='user'?'user':m.role==='system'?'system':''}"><div class="speaker">${m.role==='user'?'You':m.role==='assistant'?(impl?'Builder':'Design agent'):'Workshop'}</div><div class="markdown-content">${renderMarkdown(m.content||'')}</div>${kind==='design'?imageReferences(m.images):''}</div>`).join(''):`<div class="message"><div class="speaker">Your workshop</div>${impl?'You’ve selected a design snapshot. Tell the builder what you’d like to create or improve.':'What do freedom and Bitcoin mean to you? Tell us about a tool you need, a vision you want to explain, or a trick you wish you could share.'}</div>`}${failed?`<div class="error-box"><strong>This turn needs attention.</strong><p>${e(failed.error||failed.progress||'The run was interrupted. Your message is saved.')}</p>${failed.status==='conflict'?`<button class="small" data-rebase="${e(failed.id)}">Rebase interview</button>`:`<button class="small" data-retry="${e(failed.id)}">Retry saved turn</button>`}</div>`:''}</div>${job?`<div class="progress" role="status"><span class="pulse"></span>${e(job.progress||job.message||'Your agent is working. It’s safe to leave this page.')} <span class="muted">(${e(job.status)})</span>${['running','uncertain','dispatching'].includes(job.status)?` <button type="button" class="small ghost" data-recover="${e(job.id)}">Check & recover</button>`:''}</div>`:''}<form class="composer" id="message-form"><label class="visually-hidden" for="message-input">${impl?'Message the builder':'Respond to your design agent'}</label><textarea id="message-input" name="message" rows="3" ${kind==='design'&&draftImages(id).length?'':'required'} placeholder="${impl?'What should we build or improve?':'Your thoughts, questions, and ideas…'}">${e(storageGet(draftKey(kind,id))||'')}</textarea>${kind==='design'?imageComposer(id,me?.integration?.interviewImages===true,!!job):''}<div class="composer-footer"><span class="help">${version?`Feedback includes artefact version ${e(version.number)}.`:impl?'Builds stay linked to the selected design.':'Replies update this design until an artefact is built.'}</span><button class="primary send" type="submit" ${job?'disabled':''}>${job?'Working…':'Send ↗'}</button></div></form></section><section class="panel preview-panel" aria-label="Design and artefact preview"><div class="panel-head"><span class="panel-label"><span class="dot ${version?'orange':''}"></span>${version?`Artefact · Version ${e(version.number)} · Preview test data${version.outdatedBrand?' · older / unknown brand':''}`:editing?'Edit design':'Design preview'}</span><div class="row">${version?`<button class="small" data-open-app="${e(version.id)}">Open app · saved data</button><a class="small" target="_blank" rel="noopener" href="${e(version.previewUrl||`/preview/${version.id}/index.html`)}">Open ↗</a>${me!.admin?`<button class="small" data-data-permissions="${e(version.artifactId)}" data-version="${e(version.id)}">Data permissions</button><button class="small" data-publish="${e(version.artifactId)}" data-version="${e(version.id)}">${version.sitePublished?'Published ✓':version.published?'Add to project site':'Publish version'}</button>`:''}`:kind==='design'?editing?'<button class="small" data-action="cancel-edit">Cancel</button><button class="primary small" data-action="save-edit">Save revision</button>':'<button class="small" data-action="edit-document">Edit design</button>':''}</div></div><div class="preview-content">${content}</div><div class="history"><div class="history-title">Design milestones <span style="color:var(--purple)">●</span> &nbsp; Artefact versions <span style="color:var(--orange)">●</span></div><div class="history-items">${(data.milestones||(data.snapshot?[{...data.snapshot,snapshotId:data.snapshot.id,number:data.designPin?.designNumber||1,state:'pinned'}]:[])).map((s:RecordData)=>`<button class="snapshot ${!version&&s.snapshotId===snap?.id?'selected':''}" data-snapshot="${e(s.snapshotId)}" title="${e(date(s.createdAt))} · ${e(s.revisionCount||1)} immutable revisions">Design ${e(s.number)} · ${e(s.state)}</button>`).join('')}${versions.map(v=>`<button class="artifact ${v.id===version?.id?'selected':''}" data-version-select="${e(v.id)}" title="${e(v.artifactTitle)}">Version ${e(v.number)}${v.published?' · public':''}${v.outdatedBrand?' · older brand':''}</button>`).join('')}${!snaps.length&&!versions.length?'<span class="help">Your saved history will appear here.</span>':''}</div></div></section></div></main>`;
if(kind==='design')mountInterviewImages((path,method,data)=>method==='POST'&&path.endsWith('/images')?runBrowserOperation(api,nstackSigner(),path,data):api(path,method,data),id,me?.integration?.interviewImages===true,!!job,modal);document.querySelector('[data-open-app]')?.addEventListener('click',()=>{if(version)openNStackApp(api,modal,{id:version.id,previewUrl:version.previewUrl,artifactTitle:version.artifactTitle},nstackSigner())});if(version){const frame=document.querySelector<HTMLIFrameElement>('.preview-content iframe');if(frame)attachNStackBridge(frame,version.id,api,'preview',nstackSigner());}document.querySelectorAll('[data-data-permissions]').forEach(el=>el.addEventListener('click',()=>act(()=>nstackPermissions(api,modal,el.getAttribute('data-data-permissions')!,el.getAttribute('data-version')!))));const newMessages=document.querySelector('.messages')!;newMessages.scrollTop=atBottom?newMessages.scrollHeight:previousScroll;if(editorScroll)document.querySelector('#document-editor')!.scrollTop=editorScroll;document.querySelector('#message-input')!.addEventListener('input',saveWorkspaceState);const chatInput=document.querySelector<HTMLTextAreaElement>('#message-input')!;chatInput.addEventListener('compositionstart',()=>{chatComposing=true});chatInput.addEventListener('compositionend',()=>{chatComposing=false;lastChatCompositionEnd=Date.now()});chatInput.addEventListener('keydown',ev=>{if(!isChatSubmitKey(ev,chatComposing,lastChatCompositionEnd))return;ev.preventDefault();const form=document.querySelector<HTMLFormElement>('#message-form')!;const submit=form.querySelector<HTMLButtonElement>('[type=submit]')!;if(!ev.repeat&&!busy&&!submit.disabled&&(chatInput.value.trim()||kind==='design'&&draftImages(id).length))form.requestSubmit();});document.querySelector('#document-editor')?.addEventListener('input',saveWorkspaceState);if(wasFocused==='message-input'){const input=document.querySelector<HTMLTextAreaElement>('#message-input')!;input.focus({preventScroll:true});if(selection!==null)input.setSelectionRange(selection,selection)}document.querySelector('#message-form')!.addEventListener('submit',ev=>{ev.preventDefault();act(()=>sendMessage(kind,id))});document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>{tab=el.getAttribute('data-tab')!;localStorage.setItem('byo-freedom.tab',tab);document.querySelector('.workspace')!.setAttribute('data-tab',tab);document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t.getAttribute('data-tab')===tab);t.setAttribute('aria-selected',String(t.getAttribute('data-tab')===tab))})}));document.querySelectorAll('[data-snapshot]').forEach(el=>el.addEventListener('click',()=>{saveWorkspaceState();selectedSnapshot=el.getAttribute('data-snapshot');selectedVersion=null;sessionStorage.setItem(`byo-freedom.selection.${kind}.${id}`,JSON.stringify({snapshotId:selectedSnapshot,versionId:null}));editing=false;act(()=>workspace(kind,id))}));document.querySelectorAll('[data-version-select]').forEach(el=>el.addEventListener('click',()=>{saveWorkspaceState();selectedVersion=el.getAttribute('data-version-select');sessionStorage.setItem(`byo-freedom.selection.${kind}.${id}`,JSON.stringify({snapshotId:null,versionId:selectedVersion}));editing=false;act(()=>workspace(kind,id))}));document.querySelectorAll('[data-rebase]').forEach(el=>el.addEventListener('click',()=>act(async()=>{const jobId=el.getAttribute('data-rebase')!;const key=`byo-freedom.rebase.${jobId}`;const requestId=storageGet(key)||crypto.randomUUID();localStorage.setItem(key,requestId);await api(`/api/jobs/${jobId}/recover`,'POST',{action:'rebase',requestId});localStorage.removeItem(key);toast('Interview continues from the latest saved design');await workspace(kind,id)})));document.querySelectorAll('[data-recover]').forEach(el=>el.addEventListener('click',()=>act(async()=>{await api(`/api/jobs/${el.getAttribute('data-recover')}/recover`,'POST',{});toast('Run status checked');await workspace(kind,id)})));document.querySelectorAll('[data-retry]').forEach(el=>el.addEventListener('click',()=>act(async()=>{await api(`/api/jobs/${el.getAttribute('data-retry')}/retry`,'POST',{});await workspace(kind,id)})));document.querySelectorAll('[data-publish]').forEach(el=>el.addEventListener('click',()=>act(async()=>{await api(`/api/artifacts/${el.getAttribute('data-publish')}/publish`,'POST',{versionId:el.getAttribute('data-version')});toast('Version published to the project site');await workspace(kind,id)})));schedulePoll(kind,id,!!job)}
function schedulePoll(kind:string,id:string,working:boolean){clearTimeout(pollTimer);pollTimer=setTimeout(()=>{if(activeRoute===`${kind}/${id}`&&!document.hidden)workspace(kind,id,true).catch(err=>{console.warn('Progress refresh failed',err);schedulePoll(kind,id,working)})},working?2500:10000)}
async function sendMessage(kind:string,id:string){if(kind==='design'&&imageUploadBusy(id))throw Error('Wait for the image upload to finish.');const imageIds=kind==='design'?draftImages(id).map(i=>i.id):[];const input=document.querySelector<HTMLTextAreaElement>('#message-input')!;const content=input.value.trim();if(!content&&!imageIds.length)return;const pendingKey=`byo-freedom.pending.${kind}.${id}`;let pending:RecordData|null=null;try{pending=JSON.parse(storageGet(pendingKey)||'null')}catch{}const data:RecordData=pending?.content===content&&(pending?.artifactVersionId??null)===(kind==='design'?selectedVersion:null)&&JSON.stringify(pending?.imageIds??[])===JSON.stringify(imageIds)?pending!:{content,requestId:crypto.randomUUID(),...(imageIds.length?{imageIds}:{})};if(kind==='design'&&selectedVersion)data.artifactVersionId=selectedVersion;localStorage.setItem(pendingKey,JSON.stringify(data));await api(`/api/${kind==='design'?'designs':'implementations'}/${id}/messages`,'POST',data);input.value='';if(kind==='design')clearDraftImages(id);localStorage.removeItem(pendingKey);localStorage.removeItem(draftKey(kind,id));await workspace(kind,id)}
async function saveEdit(rename=false){const design=current!.design;const snaps=current!.snapshots||[];const latest=snaps.find((s:RecordData)=>s.id===design.currentSnapshotId)||snaps.at(-1);const selected=snaps.find((s:RecordData)=>s.id===selectedSnapshot)||latest;if(rename){modal('Name your design',`<label>Design title<input name="title" value="${e(design.title)}" required maxlength="160"></label><div class="modal-actions"><button type="submit" class="primary">Save title</button></div>`,async form=>{await api(`/api/designs/${design.id}`,'PATCH',{title:new FormData(form).get('title'),document:latest?.document||`# ${new FormData(form).get('title')}\n\n## Open questions\nWhat would give you more freedom?`,expectedSnapshotId:design.currentSnapshotId||null});selectedSnapshot=null;await workspace('design',design.id)});return}const documentText=document.querySelector<HTMLTextAreaElement>('#document-editor')!.value;const base=JSON.parse(sessionStorage.getItem(`byo-freedom.edit-base.${design.id}`)||JSON.stringify({snapshotId:design.currentSnapshotId||null,title:design.title}));try{await api(`/api/designs/${design.id}`,'PATCH',{title:base.title,document:documentText,expectedSnapshotId:base.snapshotId});editing=false;selectedSnapshot=null;selectedVersion=null;sessionStorage.removeItem(`byo-freedom.edit.${design.id}`);await workspace('design',design.id);toast('Design updated; immutable revision saved')}catch(err){if((err as any).status===409){modal('Your design changed',`<p>A new snapshot was saved while you were editing. Your draft is preserved in this browser.</p><p class="muted">Reload the latest design, compare it with your draft, and save your changes again.</p><div class="modal-actions"><button type="submit" class="primary">Load latest snapshot</button></div>`,async()=>{editing=false;selectedSnapshot=null;await workspace('design',design.id)})}else throw err}}
async function act(fn:()=>Promise<any>){if(busy)return;busy=true;try{await fn()}catch(err){fail(err)}finally{busy=false}}
let siteState:RecordData|null=null, siteDraft:RecordData|null=null;
const siteDraftKey=(id:string)=>`byo-freedom.site-draft.${me!.pubkey}.${id}`;
function persistSiteDraft(){if(siteState&&siteDraft)localStorage.setItem(siteDraftKey(siteState.draft.projectId),JSON.stringify(siteDraft))}
function collectSiteDraft(){if(!siteDraft)return;const form=document.querySelector<HTMLFormElement>('#site-form');if(!form)return;const f=new FormData(form);siteDraft.title=String(f.get('title')||'');siteDraft.layout=String(f.get('layout'));for(const key of ['logoUrl','primary','background','text','font','buttonStyle','tone','guidance'])siteDraft.brand[key]=String(f.get(`brand.${key}`)||'');siteDraft.homePageId=f.get('homePageId')||null;siteDraft.pages.forEach((page:RecordData)=>{for(const key of ['label','slug','artifactVersionId'])page[key]=String(f.get(`page.${page.id}.${key}`)||'');page.visible=f.has(`page.${page.id}.visible`)});siteDraft.footerLinks=siteDraft.footerLinks.map((link:RecordData,i:number)=>({label:String(f.get(`footer.${i}.label`)||''),url:String(f.get(`footer.${i}.url`)||'')}));persistSiteDraft();const status=document.querySelector('#site-save-status');if(status)status.textContent='Unsaved changes · kept in this browser';}
async function renderSiteBuilder(id:string,discard=false){if(!me!.admin)throw Error('Admin access is required.');const data=await api(`/api/projects/${id}/site`);siteState=data;siteDraft=structuredClone(data.draft);if(discard)localStorage.removeItem(siteDraftKey(id));else{try{const saved=JSON.parse(storageGet(siteDraftKey(id))||'null');if(saved&&saved.projectId===id)siteDraft=saved}catch{}}paintSiteBuilder();}
function siteVersionOptions(selected:string){const all=(siteState!.artifacts||[]).flatMap((a:RecordData)=>(a.versions||[]).map((v:RecordData)=>({...v,artifactTitle:a.title})));return `<option value="">Choose an exact artefact version</option>${all.map((v:RecordData)=>`<option value="${e(v.id)}" ${v.id===selected?'selected':''}>${e(v.artifactTitle)} · v${e(v.number)}${!v.outdatedBrand&&v.brandRevision===siteDraft!.brand.revision?'':' · older / unknown brand'}</option>`).join('')}`}
function paintSiteBuilder(){const d=siteDraft!,state=siteState!,id=d.projectId;const dirty=!!storageGet(siteDraftKey(id));const conflict=d.revision!==state.draft.revision;app.innerHTML=header()+`<main class="shell site-builder">${breadcrumb([['My Projects','/projects'],[state.project?.title||d.title,`/projects/${id}`],['Site Builder']])}<div class="heading-row"><div><div class="eyebrow">One project. One website.</div><h1>Site Builder</h1><p class="intro">Bring selected artefacts together with shared navigation and a project identity.</p></div><a href="/sites/${e(id)}/" target="_blank" rel="noopener" class="small">View public site ↗</a></div><div class="site-status"><span class="badge">Private draft · revision ${e(d.revision)}</span><span id="site-save-status" role="status">${dirty?'Unsaved changes · kept in this browser':'All changes saved'}</span><span>${state.publishedReleaseId?'Published release available':'No site release published'}</span></div>${conflict?'<div class="error-box" role="alert">A newer draft exists on the server. Your local edits are preserved. Compare them before discarding or restoring them on the latest draft.</div>':''}<form id="site-form"><div class="site-columns"><div class="site-main"><section class="card site-section"><div class="section-row"><div><h2>Pages & navigation</h2><p class="help">Choose exact versions. Page order is navigation order; hidden navigation pages still have public addresses after publication.</p></div><button type="button" id="site-add-page" class="small">+ Add page</button></div>${d.pages.length?`<div class="site-pages">${d.pages.map((page:RecordData,i:number)=>`<fieldset class="site-page"><legend>Page ${i+1}</legend><div class="site-page-head"><label class="check-label"><input type="radio" name="homePageId" value="${e(page.id)}" ${page.id===d.homePageId?'checked':''}>Homepage</label><div class="row"><button type="button" class="small" data-page-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move page ${i+1} up">↑</button><button type="button" class="small" data-page-move="${i}" data-direction="1" ${i===d.pages.length-1?'disabled':''} aria-label="Move page ${i+1} down">↓</button><button type="button" class="small danger" data-page-remove="${i}">Remove</button></div></div><label>Artefact version<select name="page.${e(page.id)}.artifactVersionId" required>${siteVersionOptions(page.artifactVersionId)}</select></label><div class="site-field-pair"><label>Navigation label<input name="page.${e(page.id)}.label" value="${e(page.label)}" required maxlength="100"></label><label>Page address<input name="page.${e(page.id)}.slug" value="${e(page.slug)}" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxlength="80" spellcheck="false"><span class="help">Lowercase words, numbers and hyphens.</span></label></div><label class="check-label"><input type="checkbox" name="page.${e(page.id)}.visible" ${page.visible?'checked':''}>Show in navigation</label><p class="help site-brand-status">${siteVersionBrandStatus(page.artifactVersionId)}</p></fieldset>`).join('')}</div>`:'<div class="empty"><h3>Give your website its first page.</h3><p>Add a tested artefact version, then choose its address and navigation label.</p></div>'}</section><section class="card site-section"><h2>Site appearance</h2><div class="site-field-pair"><label>Site title<input name="title" required maxlength="150" value="${e(d.title)}"></label><label>Layout<select name="layout">${[['simple','Simple website'],['resource-library','Resource library'],['event-hub','Event hub']].map(([value,label])=>`<option value="${value}" ${d.layout===value?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="help">Layouts change the shared site shell. Existing artefact content keeps its original design.</p></section><section class="card site-section"><div class="section-row"><h2>Footer links</h2><button type="button" id="site-add-footer" class="small">+ Add link</button></div>${d.footerLinks.map((link:RecordData,i:number)=>`<div class="site-footer-row"><label>Label<input name="footer.${i}.label" value="${e(link.label)}" required maxlength="100"></label><label>URL<input name="footer.${i}.url" value="${e(link.url)}" required placeholder="https://… or /sites/…"></label><button type="button" class="small danger" data-footer-remove="${i}" aria-label="Remove footer link ${i+1}">Remove</button></div>`).join('')||'<p class="help">Add useful links for your visitors.</p>'}</section></div><aside class="card site-section site-brand"><div class="eyebrow">Shared by new builds</div><h2>Project brand</h2><p class="help">Saved branding goes to the interviewer and builder. Each design can record an explicit exception. Earlier HTML needs rebuilding to adopt changes.</p><label>Logo URL<input name="brand.logoUrl" value="${e(d.brand.logoUrl)}" placeholder="https://…" type="url"></label><div class="site-colours">${[['primary','Accent'],['background','Background'],['text','Text']].map(([key,label])=>`<label>${label}<input name="brand.${key}" type="color" value="${e(d.brand[key])}"></label>`).join('')}</div><label>Font family<select name="brand.font">${[['system','System sans serif'],['serif','Serif'],['mono','Monospace']].map(([v,label])=>`<option value="${v}" ${d.brand.font===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Button shape<select name="brand.buttonStyle">${['rounded','square','pill'].map(v=>`<option value="${v}" ${d.brand.buttonStyle===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Tone of voice<textarea name="brand.tone" rows="3" maxlength="1000" placeholder="Clear, welcoming and practical…">${e(d.brand.tone)}</textarea></label><label>Design guidance<textarea name="brand.guidance" rows="6" maxlength="10000" placeholder="Purpose, accessibility, imagery, and rules for new builds…">${e(d.brand.guidance)}</textarea></label><p class="help">Current brand revision ${e(state.draft.brand.revision)}. Builds retain the revision they received.</p></aside></div><div class="site-actions"><button class="primary" type="submit">Save draft</button><button type="button" id="site-preview">Private preview</button><button type="button" id="site-publish" class="accent">Publish website</button><button type="button" id="site-discard" class="ghost small">Reload saved draft</button></div><div id="site-error" role="alert"></div></form><section class="site-section"><div class="section-row"><h2>Publication history</h2><span class="help">Each release preserves exact pages, navigation and theme.</span></div><div class="design-list">${(state.publications||[]).map((r:RecordData,i:number)=>`<div class="card site-release"><div><strong>${e(r.title||`Site release ${i+1}`)}</strong><p class="help">${e(date(r.createdAt))} · ${r.id===state.publishedReleaseId?'Current public release':'Immutable saved release'} · ${e(r.id.slice(0,8))}</p></div><div class="row"><a class="small" href="/sites/${e(id)}/releases/${e(r.id)}/" target="_blank" rel="noopener">View release ↗</a>${r.id===state.publishedReleaseId?'':`<button class="small" data-site-rollback="${e(r.id)}">Restore release</button>`}</div></div>`).join('')||'<p class="help">Published site releases will appear here.</p>'}</div></section></main>`;
const form=document.querySelector<HTMLFormElement>('#site-form')!;form.addEventListener('input',collectSiteDraft);form.addEventListener('change',collectSiteDraft);form.addEventListener('submit',ev=>{ev.preventDefault();siteAction(async()=>{await saveSiteDraft();toast('Site draft saved');paintSiteBuilder()})});document.querySelector('#site-add-page')!.addEventListener('click',()=>{collectSiteDraft();const page={id:crypto.randomUUID(),artifactVersionId:'',slug:`page-${d.pages.length+1}`,label:`Page ${d.pages.length+1}`,visible:true};d.pages.push(page);if(!d.homePageId)d.homePageId=page.id;persistSiteDraft();paintSiteBuilder()});document.querySelectorAll('[data-page-remove]').forEach(el=>el.addEventListener('click',()=>{collectSiteDraft();const removed=d.pages.splice(Number(el.getAttribute('data-page-remove')),1)[0];if(removed.id===d.homePageId)d.homePageId=d.pages[0]?.id||null;persistSiteDraft();paintSiteBuilder()}));document.querySelectorAll('[data-page-move]').forEach(el=>el.addEventListener('click',()=>{collectSiteDraft();const i=Number(el.getAttribute('data-page-move')),j=i+Number(el.getAttribute('data-direction'));[d.pages[i],d.pages[j]]=[d.pages[j],d.pages[i]];persistSiteDraft();paintSiteBuilder()}));document.querySelector('#site-add-footer')!.addEventListener('click',()=>{collectSiteDraft();d.footerLinks.push({label:'',url:''});persistSiteDraft();paintSiteBuilder()});document.querySelectorAll('[data-footer-remove]').forEach(el=>el.addEventListener('click',()=>{collectSiteDraft();d.footerLinks.splice(Number(el.getAttribute('data-footer-remove')),1);persistSiteDraft();paintSiteBuilder()}));document.querySelector('#site-discard')!.addEventListener('click',()=>modal('Reload the saved draft?',`<p>This discards your browser’s unsaved Site Builder edits and loads the current server draft.</p><div class="modal-actions"><button type="submit" class="primary">Discard local edits & reload</button></div>`,async()=>renderSiteBuilder(id,true)));document.querySelector('#site-preview')!.addEventListener('click',()=>siteAction(async()=>{await saveSiteDraft();paintSiteBuilder();const preview=await api(`/api/projects/${id}/site/preview`,'POST',{expectedRevision:siteDraft!.revision});const box=modal('Private site preview',`<p class="help">Authenticated preview of saved draft revision ${e(siteDraft!.revision)}. Publishing is a separate action.</p><iframe class="site-preview-frame" sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer" title="Private site preview"></iframe>`);box.querySelector('.modal')!.classList.add('site-preview-modal');const frame=box.querySelector('iframe')!;frame.addEventListener('load',()=>frame.contentWindow?.postMessage({type:'byo-site-preview',html:preview.html},'*'),{once:true});frame.src='/site-preview-host';}));document.querySelector('#site-publish')!.addEventListener('click',()=>siteAction(async()=>{await saveSiteDraft();paintSiteBuilder();const snapshot=structuredClone(siteDraft!);const ids=[...new Set(snapshot.pages.map((p:RecordData)=>p.artifactVersionId))];const requestId=crypto.randomUUID();modal('Publish this website?',`<p>This makes the selected exact artefact versions publicly accessible, including versions that are currently private. Other versions and interview history stay private.</p><ul>${snapshot.pages.map((p:RecordData)=>`<li>${e(p.label)} · ${e(p.slug)} · version ${e(p.artifactVersionId.slice(0,8))}</li>`).join('')}</ul><label class="check-label"><input type="checkbox" name="confirm" required>I intend to expose these selected versions publicly.</label><div class="modal-actions"><button type="submit" class="accent">Publish selected versions</button></div>`,async()=>{await api(`/api/projects/${id}/site/publish`,'POST',{expectedRevision:snapshot.revision,requestId,exposeVersionIds:ids});await renderSiteBuilder(id,true);toast('Website published as an immutable release')})}));document.querySelectorAll('[data-site-rollback]').forEach(el=>el.addEventListener('click',()=>{const releaseId=el.getAttribute('data-site-rollback')!;const requestId=crypto.randomUUID();modal('Restore this release?',`<p>The public website will point to this release’s exact versions, navigation and theme. Your private draft stays saved.</p><div class="modal-actions"><button type="submit" class="primary">Restore public release</button></div>`,async()=>{await api(`/api/projects/${id}/site/rollback`,'POST',{releaseId,requestId});await renderSiteBuilder(id);toast('Public release restored')})}));}
function siteVersionBrandStatus(versionId:string){const v=(siteState!.artifacts||[]).flatMap((a:RecordData)=>a.versions||[]).find((v:RecordData)=>v.id===versionId);if(!v)return 'Select an artefact version to see its brand status.';return !v.outdatedBrand&&v.brandRevision===siteState!.draft.brand.revision?`Built with current brand revision ${e(v.brandRevision)}.`:`Older or unknown brand revision (${e(v.brandRevision??'not recorded')}). Rebuild to apply current guidance; this page keeps its original appearance.`}
async function saveSiteDraft(){collectSiteDraft();const id=siteDraft!.projectId;const saved=await api(`/api/projects/${id}/site`,'PUT',{expectedRevision:siteDraft!.revision,draft:siteDraft});const fresh= saved.draft? saved:await api(`/api/projects/${id}/site`);siteState={...siteState,...fresh};siteDraft=structuredClone(siteState!.draft);localStorage.removeItem(siteDraftKey(id));}
async function siteAction(fn:()=>Promise<any>){await act(async()=>{try{await fn()}catch(err){const box=document.querySelector('#site-error');if(box){box.className='error-box';box.textContent=(err as any).status===409?'The server draft changed. Your edits are preserved in this browser. Reload the saved draft only when you are ready to discard or compare them.':(err as Error).message}throw err}})}
async function designBrandExceptions(designId:string){const brand=await api(`/api/designs/${designId}/brand`);modal('Design brand exceptions',`<p class="muted">This design inherits the project brand. Record any deliberate differences for both the interviewer and builder.</p><label>Explicit exceptions<textarea name="exceptions" rows="6" maxlength="8000" placeholder="Leave empty to inherit the project brand fully.">${e(brand.exceptions)}</textarea></label><div class="modal-actions"><button type="submit" class="primary">Save exceptions</button></div>`,async form=>{await api(`/api/designs/${designId}/brand`,'PATCH',{expectedRevision:brand.revision,exceptions:String(new FormData(form).get('exceptions')||'')});toast('Design brand exceptions saved')})}

async function renderInstalledApp(versionId:string){const token=generation;const launch=await api(`/api/installed-apps/${encodeURIComponent(versionId)}`);if(token!==generation)return;app.innerHTML=header()+`<main class="shell"><div>${breadcrumb([['My Projects','/projects'],[launch.project.title,`/projects/${launch.project.id}`],[launch.title]])}</div><div class="heading-row"><div><h1>${e(launch.title)}</h1><p class="help">Version ${e(launch.number)} · Saved app data · Project members only</p></div></div><p class="help">This exact installed version uses live saved data. The app has no access to your signer or private design conversations.</p><iframe class="site-preview-frame" id="installed-app-frame" title="${e(launch.title)} — saved app data" sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer"></iframe></main>`;const frame=document.querySelector<HTMLIFrameElement>('#installed-app-frame')!;attachNStackBridge(frame,launch.versionId,api,'live',nstackSigner());frame.src=launch.previewUrl;}
async function route(){saveWorkspaceState();chatComposing=false;generation++;clearTimeout(pollTimer);activeRoute='';lastRenderKey='';selectedSnapshot=null;selectedVersion=null;editing=false;const path=location.hash.replace(/^#/,'')||'/projects';const bits=path.split('/');if(bits[1]==='designs'||bits[1]==='implementations'){try{const selection=JSON.parse(sessionStorage.getItem(`byo-freedom.selection.${bits[1]==='designs'?'design':'implementation'}.${bits[2]}`)||'null');selectedSnapshot=selection?.snapshotId||null;selectedVersion=selection?.versionId||null}catch{}}if(!storageGet(MODE)){if(/^\/apps\/[^/?#]+$/.test(path))sessionStorage.setItem('byo-freedom.return-app',path);renderEntry();return}if(!me){try{await loadMe()}catch(err){renderEntry();fail(err);return}}try{if(sessionStorage.getItem(INVITE_KEY)){try{const destination=await joinPendingInvite();if(destination){history.replaceState(null,'','/'+destination);await renderProject(destination.split('/')[2]);return}}catch(err){app.innerHTML=header()+`<main class="standalone-error"><h1>We couldn’t join that project.</h1><p class="muted">${e((err as Error).message)}</p><p>Your invitation is saved. Check the code with the organiser or retry if signing or the connection failed.</p><div class="row"><button data-action="retry-invite">Retry invitation</button><button data-action="dismiss-invite">Enter a code manually</button></div></main>`;return}}if(/^\/apps\/[^/]+$/.test(path))await renderInstalledApp(path.split('/')[2]);else if(path==='/profile')await profile();else if(/^\/projects\/[^/]+\/site$/.test(path))await renderSiteBuilder(path.split('/')[2]);else if(/^\/projects\/[^/]+$/.test(path))await renderProject(path.split('/')[2]);else if(/^\/designs\/[^/]+$/.test(path))await workspace('design',path.split('/')[2]);else if(/^\/implementations\/[^/]+$/.test(path))await workspace('implementation',path.split('/')[2]);else await renderProjects()}catch(err){app.innerHTML=header()+`<main class="standalone-error"><h1>We couldn’t open this page.</h1><p class="muted">${e((err as Error).message)}</p><a href="#/projects">Back to My Projects</a></main>`}}
document.addEventListener('click',ev=>{const el=(ev.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!el)return;const action=el.dataset.action;act(async()=>{switch(action){case 'retry-invite':await route();break;case 'dismiss-invite':sessionStorage.removeItem(INVITE_KEY);history.replaceState(null,'','/#/projects');await route();break;case 'share-project':await shareProject();break;case 'nstack-settings':await nstackSettings(api,modal,nstackSigner());break;case 'anon':await login('anon');break;case 'extension':await login('extension');break;case 'import':restore();break;case 'profile':location.hash='#/profile';break;case 'projects':location.hash='#/projects';break;case 'export':exportKey();break;case 'logout':saveWorkspaceState();localStorage.removeItem(MODE);me=null;renderEntry();break;case 'new-project':createProject();break;case 'featured':featured();break;case 'new-design':await newDesign();break;case 'project-settings':projectSettings();break;case 'delete-project':deleteProject();break;case 'design-brand':await designBrandExceptions(current!.design.id);break;case 'implement-current':await selectImplementation(current!.design.id);break;case 'rename':await saveEdit(true);break;case 'edit-document':selectedVersion=null;sessionStorage.setItem(`byo-freedom.edit-base.${current!.design.id}`,JSON.stringify({snapshotId:current!.design.currentSnapshotId||null,title:current!.design.title}));editing=true;await workspace('design',current!.design.id);break;case 'cancel-edit':editing=false;await workspace('design',current!.design.id);break;case 'save-edit':await saveEdit();break;}})});
window.addEventListener('hashchange',()=>route());window.addEventListener('beforeunload',saveWorkspaceState);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&activeRoute){const [kind,id]=activeRoute.split('/');workspace(kind,id,true).catch(fail)}});route();
